-- Notification, DailyNote.
--
-- Notification: most rows (source_type 'system' or 'teacher', e.g.
-- assignment-published fan-out, daily-note fan-out) are generated by the
-- background job / business-logic layer (Doc 8 "Notification Delivery
-- Architecture"), not written directly by an authenticated client role --
-- so there is no generic client insert policy here. The one client-facing
-- write is the admin's own "Send fee reminders" / "Send school-wide
-- announcements" actions (Doc 6), scoped to source_type = 'admin' and
-- restricted to those two categories.
--
-- DailyNote is immutable at the DB level already (forbid_dailynote_mutation
-- trigger, notifications migration); no update/delete policy is added for
-- anyone here, which is redundant with the trigger but keeps RLS and the
-- trigger each independently sufficient.
-- Admin visibility into DailyNote content is NOT granted here: unlike
-- Notification ("Admin Visibility: Notification Log", Doc 8) and unlike
-- every other academic-activity table, no doc grants admin read access to
-- DailyNote specifically -- Doc 23 Section 6's consolidated matrix omits it
-- entirely. Revisit if a future doc adds it; don't infer it from the
-- general oversight pattern elsewhere.

alter table "Notification" enable row level security;

create policy "notification_select_own" on "Notification"
  as permissive for select to authenticated
  using (membership_id = auth_membership_id());

-- Doc 8: "mark-as-read-on-open" -- family toggles read_status on their own
-- notifications.
create policy "notification_update_own" on "Notification"
  as permissive for update to authenticated
  using (membership_id = auth_membership_id())
  with check (membership_id = auth_membership_id());

create policy "notification_select_admin" on "Notification"
  as permissive for select to authenticated
  using (
    auth_app_role() = 'admin'
    and exists (
      select 1 from "FamilyMembership" fm
      where fm.membership_id = "Notification".membership_id and fm.school_id = auth_school_id()
    )
  );

create policy "notification_insert_admin" on "Notification"
  as permissive for insert to authenticated
  with check (
    auth_app_role() = 'admin'
    and source_type = 'admin'
    and category in ('fee', 'announcement')
    and exists (
      select 1 from "FamilyMembership" fm
      where fm.membership_id = "Notification".membership_id and fm.school_id = auth_school_id()
    )
  );

create policy "notification_all_platform_admin" on "Notification"
  as permissive for all to authenticated
  using (is_platform_admin())
  with check (is_platform_admin());

alter table "DailyNote" enable row level security;

create policy "dailynote_insert_teacher_assigned" on "DailyNote"
  as permissive for insert to authenticated
  with check (
    auth_app_role() = 'teacher'
    and teacher_id = auth_teacher_id()
    and exists (
      select 1
      from "ClassMembership" cm
      join "TeacherClassAssignment" tca on tca.class_id = cm.class_id
      where cm.enrollment_id = "DailyNote".enrollment_id and tca.teacher_id = auth_teacher_id()
    )
  );

-- Scoped to the authoring teacher, not the whole assigned class -- these are
-- free-form health/behavior/academic observations about a specific child,
-- and no doc grants a co-teacher visibility into a colleague's notes.
create policy "dailynote_select_own" on "DailyNote"
  as permissive for select to authenticated
  using (auth_app_role() = 'teacher' and teacher_id = auth_teacher_id());

create policy "dailynote_select_own_children" on "DailyNote"
  as permissive for select to authenticated
  using (
    exists (
      select 1 from "SchoolEnrollment" se
      join "FamilyStudentRelationship" fsr on fsr.platform_student_id = se.platform_student_id
      where se.enrollment_id = "DailyNote".enrollment_id and fsr.membership_id = auth_membership_id()
    )
  );

create policy "dailynote_all_platform_admin" on "DailyNote"
  as permissive for all to authenticated
  using (is_platform_admin())
  with check (is_platform_admin());
